251	    @Override
252	    @Transactional
253	    public void createOwner(Owner owner, boolean sharesHousehold) throws DataAccessException {
254	        assignHousehold(owner, sharesHousehold);
255	        if (owner.getCustomerCode() == null) {
256	            owner.setCustomerCode(nextCustomerCode(owner.getLastName()));
257	        }
258	        ownerRepository.save(owner);
259	    }
260	
261	    /**
262	     * Reconcile the owner's household. Owners are in the same household when their last name and
263	     * address match (compared case-insensitively with collapsed whitespace). When another owner
264	     * already lives there, the create is rejected with {@link DuplicateHouseholdException} unless
265	     * {@code sharesHousehold} is set, in which case the new owner and every existing member are
266	     * given the same stable shared {@code householdId}.
267	     */
268	    private void assignHousehold(Owner owner, boolean sharesHousehold) {
269	        String lastName = IdentityNormalizer.normalize(owner.getLastName());
270	        String address = AddressNormalizer.canonical(owner.getAddress());
271	        List<Owner> householdMembers = ownerRepository.findAll().stream()
272	            .filter(existing -> lastName.equals(IdentityNormalizer.normalize(existing.getLastName()))
273	                && address.equals(AddressNormalizer.canonical(existing.getAddress())))
274	            .toList();
275	        if (householdMembers.isEmpty()) {
276	            return;
277	        }
278	        if (!sharesHousehold) {
279	            throw new DuplicateHouseholdException(
280	                "an owner with last name " + owner.getLastName() + " already lives at " + owner.getAddress());
281	        }
282	        String householdId = householdMembers.stream()
283	            .map(Owner::getHouseholdId)
284	            .filter(Objects::nonNull)
285	            .findFirst()
286	            .orElseGet(() -> deriveHouseholdId(lastName, address));
287	        owner.setHouseholdId(householdId);
288	        for (Owner member : householdMembers) {
289	            if (!householdId.equals(member.getHouseholdId())) {
290	                member.setHouseholdId(householdId);
291	                ownerRepository.save(member);
292	            }
293	        }
294	    }
295	
296	    /**
297	     * Derive a stable, shared household identifier from the normalized last name and address, so
298	     * every owner in the same household deterministically maps to the same value.
299	     */
300	    private static String deriveHouseholdId(String normalizedLastName, String normalizedAddress) {
301	        String key = normalizedLastName + "\n" + normalizedAddress;
302	        return UUID.nameUUIDFromBytes(key.getBytes(StandardCharsets.UTF_8)).toString();
303	    }
304	
305	    /**
306	     * Builds the customer code {@code '<LAST3>-<NNNN>'}: the upper-cased first three
307	     * letters of {@code lastName}, a hyphen, and a global 4-digit zero-padded sequence
308	     * equal to one more than the current number of owners.
309	     */
310	    private String nextCustomerCode(String lastName) {
311	        String name = lastName == null ? "" : lastName;
312	        String last3 = name.substring(0, Math.min(3, name.length())).toUpperCase();
313	        long sequence = ownerRepository.findAll().size() + 1L;
314	        return String.format("%s-%04d", last3, sequence);
315	    }
